/**
 * Whipler Design — Portfolio Lightbox
 * Vanilla JS, no dependencies.
 * Include at bottom of <body> or in your main bundle.
 * Works with HTML generated by generate_design_thumbs.py
 */

(function () {
  "use strict";

  // ── Build lightbox DOM ──────────────────────────────────────
  const backdrop = document.createElement("div");
  backdrop.className = "wd-lightbox-backdrop";
  backdrop.setAttribute("aria-modal", "true");
  backdrop.setAttribute("role", "dialog");
  backdrop.setAttribute("aria-label", "Image viewer");

  backdrop.innerHTML = `
    <button class="wd-lightbox-close" aria-label="Close">&times;</button>
    <button class="wd-lightbox-prev" aria-label="Previous">&#8249;</button>
    <div class="wd-lightbox-inner">
      <img class="wd-lightbox-img" src="" alt="">
    </div>
    <button class="wd-lightbox-next" aria-label="Next">&#8250;</button>
    <span class="wd-lightbox-counter"></span>
  `;
  document.body.appendChild(backdrop);

  const lbImg     = backdrop.querySelector(".wd-lightbox-img");
  const lbClose   = backdrop.querySelector(".wd-lightbox-close");
  const lbPrev    = backdrop.querySelector(".wd-lightbox-prev");
  const lbNext    = backdrop.querySelector(".wd-lightbox-next");
  const lbCounter = backdrop.querySelector(".wd-lightbox-counter");

  // ── State ───────────────────────────────────────────────────
  let triggers = [];   // all .wd-lightbox-trigger elements
  let current  = -1;   // index of currently shown image

  function getTriggers() {
    // Exclude PDFs — they open in a new tab, not the lightbox
    triggers = Array.from(document.querySelectorAll("a.wd-lightbox-trigger:not([data-type='pdf'])"));
  }

  // ── Open / close ────────────────────────────────────────────
  function open(index) {
    getTriggers();
    if (!triggers.length) return;
    current = ((index % triggers.length) + triggers.length) % triggers.length;
    showCurrent();
    backdrop.classList.add("is-open");
    document.body.style.overflow = "hidden";
    lbClose.focus();
  }

  function close() {
    backdrop.classList.remove("is-open");
    document.body.style.overflow = "";
    // Return focus to trigger that opened it
    if (current >= 0 && triggers[current]) {
      triggers[current].focus();
    }
    lbImg.src = "";
  }

  function showCurrent() {
    const trigger = triggers[current];
    const src  = trigger.dataset.full || trigger.getAttribute("href");
    const alt  = trigger.querySelector("img")?.alt || "";

    // Swap in a fresh animation each time
    lbImg.classList.remove("wd-lb-loaded");
    lbImg.src = src;
    lbImg.alt = alt;

    lbCounter.textContent = `${current + 1} / ${triggers.length}`;

    lbPrev.style.display = triggers.length > 1 ? "" : "none";
    lbNext.style.display = triggers.length > 1 ? "" : "none";
  }

  // ── Event listeners ─────────────────────────────────────────
  document.addEventListener("click", function (e) {
    const trigger = e.target.closest("a.wd-lightbox-trigger");
    if (!trigger) return;
    e.preventDefault();

    // PDFs open in a new tab instead of the lightbox
    if (trigger.dataset.type === "pdf") {
      window.open(trigger.dataset.full || trigger.getAttribute("href"), "_blank");
      return;
    }

    getTriggers();
    const idx = triggers.indexOf(trigger);
    open(idx >= 0 ? idx : 0);
  });

  lbClose.addEventListener("click", close);

  // Close on backdrop click (but not image click)
  backdrop.addEventListener("click", function (e) {
    if (e.target === backdrop) close();
  });

  lbPrev.addEventListener("click", function (e) {
    e.stopPropagation();
    open(current - 1);
  });

  lbNext.addEventListener("click", function (e) {
    e.stopPropagation();
    open(current + 1);
  });

  // Keyboard navigation
  document.addEventListener("keydown", function (e) {
    if (!backdrop.classList.contains("is-open")) return;
    switch (e.key) {
      case "Escape":    close();           break;
      case "ArrowLeft": open(current - 1); break;
      case "ArrowRight":open(current + 1); break;
    }
  });

  // Touch swipe support
  let touchStartX = null;
  backdrop.addEventListener("touchstart", function (e) {
    touchStartX = e.touches[0].clientX;
  }, { passive: true });
  backdrop.addEventListener("touchend", function (e) {
    if (touchStartX === null) return;
    const delta = e.changedTouches[0].clientX - touchStartX;
    if (Math.abs(delta) > 50) {
      open(delta < 0 ? current + 1 : current - 1);
    }
    touchStartX = null;
  });

})();